31	void RankInfoDetectService::Setup()
32	{
33	    // 1. 连接所有rank
34	    GetConnections();
35	
36	    // 2. 接收所有rank发来的localRankTable并整合为全局RankTable
37	    GetRankTable();
38	
39	    // 3. 将完整RankTable广播给所有rank
