43	void RankInfoDetectService::GetConnections()
44	{
45	    HCCL_INFO("[RankInfoDetectService::%s] start.", __func__);
46	
47	    // 超时参数
48	    auto startTime = std::chrono::steady_clock::now();
49	    auto timeout = std::chrono::seconds(EnvConfig::GetInstance().GetSocketConfig().GetLinkTimeOut());
50	    bool isFirstAcceptTimeOut = false;
51	
52	    // 期望等待连接的rank数量
53	    u32 expectedSocketNum = 1;
54	
55	    // 首个connect获取到的rankSize
56	    u32 previousRankNum = 0;
57	
58	    // 获取server端socket信息
59	    u32 hostPort = serverSocket_->GetListenPort();
60	    auto hccpHostSocketHandle = HostSocketHandleManager::GetInstance().Get(devPhyId_, hostIp_);
61	    CHK_PRT_THROW(
62	        hccpHostSocketHandle == nullptr,
63	        HCCL_ERROR("[RankInfoDetectService::%s] Get hccpHostSocketHandle fail.", __func__), InternalException,
64	        "get socket handle error");
65	    std::string connSocketTag = RANK_INFO_DETECT_TAG + "_" + identifier_ + "_" + std::to_string(hostPort);
66	    SocketStatus status = SocketStatus::INVALID;
67	
68	    // 连接rankSize个client
69	    while (expectedSocketNum > 0) {
70	        auto topoExUsedTime = std::chrono::steady_clock::now() - startTime;
71	        if (topoExUsedTime >= timeout) {
72	            RPT_INPUT_ERR(
73	                true, "EI0015", std::vector<std::string>({"error_reason"}),
74	                std::vector<std::string>({StringFormat(
75	                    "Receiving message from the root node timed out. "
76	                    "Timeout was set to %lld seconds. expected %u nodes, received %u nodes. "
77	                    "Check whether worker nodes are reachable and report errors.",
78	                    static_cast<long long>(timeout.count()), expectedSocketNum + previousRankNum, previousRankNum)}));
79	            HCCL_ERROR("[RankInfoDetectService::%s] server get sockets timeout[%lld s]", __func__, timeout);
80	            break;
81	        }
82	
83	        // duration_cast<seconds> 会进行向下取整，不足 1s
84	        // 时提前跳出，确保建链超时场景，server端在client端退出前发送临终遗言
85	        auto topoExResTime = timeout - topoExUsedTime;
86	        u32 topoExRes_i = std::chrono::duration_cast<std::chrono::seconds>(topoExResTime).count();
87	        if (topoExRes_i == 0) {
88	            HCCL_ERROR("[RankInfoDetectService::%s] timeout[%lld s] is exhausted", __func__, timeout);
89	            break;
90	        }
91	        std::shared_ptr<Socket> connSocket = std::make_shared<Socket>(
92	            hccpHostSocketHandle, hostIp_, hostPort, hostIp_, connSocketTag, SocketRole::SERVER,
93	            NicType::HOST_NIC_TYPE);
94	        // GetStatus 是阻塞接口，传入剩余时间作为超时上限，避免其内部超时导致外层循环超时处理失效
95	        EXCEPTION_CATCH(status = connSocket->GetStatus(topoExRes_i), {
96	            // 非本端client首次连接异常，直接重试
97	            if (status == SocketStatus::OK) {
98	                status = SocketStatus::CONNECTING;
99	            }
100	            HCCL_ERROR("[RankInfoDetectService::%s] server get socket fail", __func__);
101	        });
102	        if (status == SocketStatus::OK) {
103	            if (!RecvAndVerifyRemoteAgentIdAndRankSize(connSocket, expectedSocketNum, previousRankNum)) {
104	                break;
105	            }
106	            expectedSocketNum--;
107	            isFirstAcceptTimeOut = false;
108	            HCCL_INFO("[RankInfoDetectService::%s] socket[%s] connect ok.", __func__, connSocket->Describe().c_str());
109	        } else if (status == SocketStatus::CONNECTING) {
110	            SaluSleep(ONE_MILLISECOND_OF_USLEEP);
111	        } else if (status == SocketStatus::TIMEOUT) {
112	            // 避免重复打印
113	            if (isFirstAcceptTimeOut) {
114	                continue;
115	            }
116	            HCCL_ERROR(
117	                "[RankInfoDetectService::%s] rank info detect server get socket timeout[%lld s]", __func__, timeout);
118	            DisplayConnectingStatus(previousRankNum, expectedSocketNum);
119	            isFirstAcceptTimeOut = true;
120	        } else {
121	            HCCL_ERROR("[RankInfoDetectService::%s] SocketStatus[%s] error", __func__, status.Describe().c_str());
122	            break;
123	        }
124	    }
125	
126	    // 如果没有连接成功的rank则退出
127	    CHK_PRT_THROW(
128	        connSockets_.size() == 0, HCCL_ERROR("[RankInfoDetectService::%s] no rank connection success.", __func__),
129	        InternalException, "no rank connection success");
130	
131	    // 处理异常流程
132	    if (expectedSocketNum > 0) {
133	        // 将建立连接超时的client信息添加到failedAgentIdList_
134	        FailedConnectionAgentIdString(previousRankNum);
135	        DisplayConnectedRanks();
136	        HCCL_INFO("[RankInfoDetectService::%s] end, there exist non-connected ranks.", __func__);
137	    } else {
138	        HCCL_INFO("[RankInfoDetectService::%s] end, all agentId get connection socket success.", __func__);
139	    }
140	}
