142	void RankInfoDetectService::GetRankTable()
143	{
144	    HCCL_INFO("[RankInfoDetectService::%s] start.", __func__);
145	
146	    // 接收localRankTable并组全局RankTableInfo
147	    rankTable_ = RankTableInfo{};
148	    for (auto& iter : connSockets_) {
149	        vector<char> rankInfoMsg{};
150	        SocketAgent socketAgent(iter.second.get());
151	        RecvRankInfoMsg(socketAgent, rankInfoMsg);
152	        ParseRankTable(rankInfoMsg);
153	    }
154	
155	    // 按照rankid排序
156	    SortRankTable();
157	
158	    // 更新当前阶段
159	    currentStep_++;
160	
161	    HCCL_INFO("[RankInfoDetectService::%s] end.", __func__);
162	}
