183	bool RankInfoDetectService::RecvRemoteAgentId(SocketAgent& connSocketAgent, std::string& agentId)
184	{
185	    HCCL_INFO("[RankInfoDetectService::%s] start.", __func__);
186	
187	    // 接收消息
188	    u64 revMsgLen = 0;
189	    char msg[MAX_AGENT_BUF_SIZE] = {0};
190	    bool ret = connSocketAgent.RecvMsg(msg, revMsgLen);
191	    CHK_PRT_RET(
192	        !ret || revMsgLen >= MAX_AGENT_BUF_SIZE,
193	        HCCL_ERROR("[RankInfoDetectService::%s] recv error, revMsgLen[%llu].", __func__, revMsgLen), false);
194	
195	    // 解析agentId
196	    msg[revMsgLen] = '\0';
197	    agentId = msg;
198	
199	    HCCL_INFO("[RankInfoDetectService::%s] agentId[%s]", __func__, agentId.c_str());
200	    return true;
201	}
