207	    // 接收rankSize
208	    u64 revMsgLen = 0;
209	    bool ret = connSocketAgent.RecvMsg(&rankSize, revMsgLen);
210	    CHK_PRT_RET(
211	        !ret, HCCL_ERROR("[RankInfoDetectService::%s] RecvMsg fail, revMsgLen[%llu].", __func__, revMsgLen), false);
212	
213	    HCCL_INFO("[RankInfoDetectService::%s] rankSize[%u]", __func__, rankSize);
