217	// 接收客户端发送的字节流形式的rankinfo消息
218	void RankInfoDetectService::RecvRankInfoMsg(SocketAgent& connSocketAgent, vector<char>& rankInfoMsg)
219	{
220	    HCCL_INFO("[RankInfoDetectService::%s] start.", __func__);
221	
222	    u64 revMsgLen = 0;
223	    std::unique_ptr<HostBuffer> msg = std::make_unique<HostBuffer>(MAX_BUFFER_LEN);
224	    char* msgAddr = reinterpret_cast<char*>(msg->GetAddr());
225	    CHK_PRT_THROW(
226	        !connSocketAgent.RecvMsg(msgAddr, revMsgLen),
227	        HCCL_ERROR("[RankInfoDetectService::%s] RecvMsg fail, revMsgLen[%llu]", __func__, revMsgLen),
228	        InvalidParamsException, "RecvMsg fail");
229	
230	    // 以vector<char>格式保存
231	    rankInfoMsg.resize(revMsgLen);
232	    rankInfoMsg.assign(msgAddr, msgAddr + revMsgLen);
233	
234	    HCCL_INFO("[RankInfoDetectService::%s] end.", __func__);
235	}
