237	// 解析接收到的rank table信息
238	void RankInfoDetectService::ParseRankTable(vector<char>& rankInfoMsg)
239	{
240	    HCCL_INFO("[RankInfoDetectService::%s] start.", __func__);
241	
242	    // 消息格式: [ranktable数据(n字节)][step(4字节)]
243	    BinaryStream binStream(rankInfoMsg);
244	
245	    // 解析localRankInfo
246	    RankTableInfo localRankInfo(binStream);
247	    localRankInfo.Dump();
248	
249	    // 解析step
250	    u32 receivedStep;
251	    binStream >> receivedStep;
252	
253	    // 校验step是否匹配
254	    CHK_PRT_THROW(
255	        receivedStep != currentStep_,
256	        HCCL_ERROR(
257	            "[RankInfoDetectService::%s] Step mismatch: received %u, expected %u", __func__, receivedStep,
258	            currentStep_),
259	        InvalidParamsException, "Step mismatch");
260	
261	    // 添加到rankTable_
262	    rankTable_.UpdateRankTable(localRankInfo);
263	
264	    HCCL_INFO("[RankInfoDetectService::%s] end.", __func__);
265	}
