267	bool RankIdCompare(const NewRankInfo& i, const NewRankInfo& j) { return (i.rankId < j.rankId); }
268	
269	void RankInfoDetectService::SortRankTable()
270	{
271	    std::sort(rankTable_.ranks.begin(), rankTable_.ranks.end(), RankIdCompare);
272	}
