274	void RankInfoDetectService::FailedConnectionAgentIdString(u32 rankSize)
275	{
276	    HCCL_INFO("[RankInfoDetectService::%s] start.", __func__);
277	
278	    std::vector<bool> connectedRank(rankSize, false);
279	    for (auto it : connSockets_) {
280	        u32 rankid = 0;
281	        HcclResult ret = SalStrToULong(it.first, HCCL_BASE_DECIMAL, rankid);
282	        CHK_PRT_RET(
283	            ret != HCCL_SUCCESS,
284	            HCCL_ERROR("[RankInfoDetectService::%s] agentId[%s] strToULong fail.", __func__, it.first.c_str()), );
285	        CHK_PRT_RET(
286	            rankid >= rankSize,
287	            HCCL_ERROR("[RankInfoDetectService::%s] invalid rank id[%u], rankSize[%u].", __func__, rankid, rankSize), );
288	        connectedRank[rankid] = true;
289	    }
290	
291	    for (u32 i = 0; i < rankSize; i++) {
292	        if (!connectedRank[i]) {
293	            if (!failedAgentIdList_.empty()) {
294	                failedAgentIdList_ += ',';
295	            }
296	            failedAgentIdList_ += std::to_string(i);
297	        }
298	    }
299	
300	    HCCL_INFO("[RankInfoDetectService::%s] end.", __func__);
301	}
302	
303	// 校验相关方法
304	bool RankInfoDetectService::RecvAndVerifyRemoteAgentIdAndRankSize(
305	    std::shared_ptr<Socket> connSocket, u32& expectedSocketNum, u32& previousRankSize)
306	{
307	    HCCL_INFO("[RankInfoDetectService::%s] start.", __func__);
308	    SocketAgent socketAgent(connSocket.get());
309	
310	    // 接收AgentId
311	    std::string agentId = "";
312	    bool ret = RecvRemoteAgentId(socketAgent, agentId);
313	    CHK_PRT_RET(!ret, HCCL_ERROR("[RankInfoDetectService::%s] RecvRemoteAgentId fail.", __func__), false);
314	
315	    // 保存connSocket
316	    auto iter = connSockets_.find(agentId);
317	    CHK_PRT_RET(
318	        iter != connSockets_.end(),
319	        HCCL_ERROR("[RankInfoDetectService::%s] agentId[%s] has been connected.", __func__, agentId.c_str()), false);
320	    connSockets_.insert({agentId, connSocket});
321	
322	    // 接收RankSize
323	    u32 rankSize = 0;
324	    ret = RecvRemoteRankSize(socketAgent, rankSize);
325	    CHK_PRT_RET(!ret, HCCL_ERROR("[RankInfoDetectService::%s] RecvRemoteAgentId fail.", __func__), false);
326	
327	    // 校验
328	    expectedSocketNum = (previousRankSize == 0) ? rankSize : expectedSocketNum;
329	    CHK_PRT_RET(
330	        !VerifyRemoteRankSize(previousRankSize, rankSize),
331	        HCCL_ERROR("[RankInfoDetectService::%s] VerifyRemoteRankSize fail, rankSize[%u]", __func__, rankSize), false);
332	
333	    HCCL_INFO("[RankInfoDetectService::%s] end.", __func__);
334	    return true;
335	}
336	
337	bool RankInfoDetectService::VerifyRemoteRankSize(u32& previousRankSize, u32 remoteRankSize) const
338	{
339	    HCCL_INFO("[RankInfoDetectService::%s] start.", __func__);
340	
341	    if (previousRankSize == 0) {
342	        previousRankSize = remoteRankSize;
343	    } else {
344	        if (previousRankSize != remoteRankSize) {
345	            HCCL_ERROR(
346	                "[RankInfoDetectService::%s] VerifyRemoteRankSize failed. remoteRankSize[%u] is different "
347	                "from previousRankSize[%u].",
348	                __func__, remoteRankSize, previousRankSize);
349	            return false;
350	        }
351	    }
352	
353	    HCCL_INFO("[RankInfoDetectService::%s] end.", __func__);
354	    return true;
355	}
356	
357	// DFX相关方法
358	void RankInfoDetectService::DisplayConnectedRanks()
359	{
360	    vector<std::string> ranksInfo;
361	    for (const auto& it : connSockets_) {
362	        ranksInfo.push_back(it.first);
363	    }
364	    u64 ranksLen = ranksInfo.size();
365	    u64 lineNum = (ranksInfo.size() % DISPLAY_RANKNUM_PERLINE == 0) ? (ranksInfo.size() / DISPLAY_RANKNUM_PERLINE) :
366	                                                                      (ranksInfo.size() / DISPLAY_RANKNUM_PERLINE + 1);
367	    HCCL_ERROR(
368	        "[RankInfoDetectService::%s] total connected num is [%llu],line num is [%llu]", __func__, ranksLen, lineNum);
369	    for (u64 i = 0; i < lineNum; i++) {
370	        std::string tmpRankList;
371	        for (u32 j = 0; j < DISPLAY_RANKNUM_PERLINE; j++) {
372	            u32 ranksInfoIndex = i * DISPLAY_RANKNUM_PERLINE + j;
373	            if (ranksInfoIndex < ranksInfo.size()) {
374	                tmpRankList += "[" + ranksInfo[ranksInfoIndex] + "]";
375	            } else {
376	                break;
377	            }
378	            tmpRankList += ((j == DISPLAY_RANKNUM_PERLINE - 1 || ranksInfoIndex == ranksInfo.size() - 1) ? ";" : ",");
379	        }
380	        HCCL_ERROR("[RankInfoDetectService::%s] connected rankinfo[LINE %llu]: %s", __func__, i, tmpRankList.c_str());
381	    }
382	}
383	
384	void RankInfoDetectService::DisplayConnectingStatus(u32 totalSockets, u32 waitSockets)
385	{
386	    if (totalSockets == 0 && waitSockets == 1) {
387	        HCCL_INFO("[RankInfoDetectService::%s] wait for first connection.", __func__);
388	        return;
389	    }
390	
391	    std::vector<bool> rankinfos(totalSockets, false);
392	    for (auto it : connSockets_) { // 建立映射
393	        u32 rankid = 0;
394	        HcclResult ret = SalStrToULong(it.first, HCCL_BASE_DECIMAL, rankid);
395	        CHK_PRT_RET(
396	            ret != HCCL_SUCCESS,
397	            HCCL_ERROR("[RankInfoDetectService::%s] agentId[%s] strToULong fail.", __func__, it.first.c_str()), );
398	        CHK_PRT_RET(
399	            rankid >= totalSockets,
400	            HCCL_ERROR(
401	                "[RankInfoDetectService::%s] invalid rankid[%u], rankSize[%u].", __func__, rankid, totalSockets), );
402	        rankinfos[rankid] = true;
403	    }
404	
405	    u32 unRankCount = 0; // 只打印前三条未建链的rank
406	    std::vector<std::string> unsocketinfos;
407	    for (u32 rankid = 0; rankid < totalSockets; rankid++) {
408	        if (unRankCount >= SOCKET_PRINT_COUNT) {
409	            break;
410	        }
411	        if (!rankinfos[rankid]) {
412	            unRankCount++;
413	            std::string rankID = std::to_string(rankid);
414	            std::string agentID = std::string(16 - rankID.length(), '0') + rankID;
415	            unsocketinfos.push_back(agentID);
416	        }
417	    }
418	
419	    std::string infoStr = "succ sockets is [" + std::to_string((totalSockets - waitSockets)) + "], waiting sockets is ["
420	                          + std::to_string(waitSockets) + "], wait sockets rankid: ";
421	    for (u32 index = 0; index < unsocketinfos.size(); index++) {
422	        if (index == (unsocketinfos.size() - 1)) {
423	            infoStr += "[" + unsocketinfos[index] + "]";
424	        } else {
425	            infoStr += "[" + unsocketinfos[index] + "],";
426	        }
427	    }
428	
429	    HCCL_INFO("[RankInfoDetectService::%s] %s", __func__, infoStr.c_str());
430	}
431	
432	void RankInfoDetectService::TearDown()
433	{
434	    HCCL_INFO("[RankInfoDetectService::%s] start.", __func__);
435	
436	    CHK_PRT_RET(!serverSocket_, HCCL_INFO("[RankInfoDetectService::%s] serverSocket is null", __func__), );
437	
438	    // close socket
439	    Disconnect();
440	
441	    // 如果白名单使能则删除白名单
442	    if (!EnvConfig::GetInstance().GetHostNicConfig().GetWhitelistDisable()) {
443	        CHK_PRT_CONT(wlistInfo_.size() == 0, HCCL_ERROR("whitelist is empty"); break);
444	        SocketHandle hostSocketHandle = HostSocketHandleManager::GetInstance().Get(devPhyId_, hostIp_);
445	        HrtRaSocketWhiteListDel(hostSocketHandle, wlistInfo_);
446	    }
447	
448	    s32 deviceLogicId = HrtGetDevice();
449	    if (EnvConfig::GetInstance().GetHostNicConfig().GetHostSocketPortRange().size() > 0
450	        || EnvConfig::GetInstance().GetHostNicConfig().GetIfBasePort() == HCCL_INVALID_PORT) {
451	        // 若开启抢占监听端口
452	        PreemptPortManager::GetInstance(deviceLogicId).Release(serverSocket_);
453	    } else {
454	        // 停止监听
455	        serverSocket_->StopListen();
456	    }
457	
458	    // deinit handle
459	    HostSocketHandleManager::GetInstance().Destroy(devPhyId_, hostIp_);
460	
461	    // deinit ra
462	    HccpPeerManager::GetInstance().DeInit(deviceLogicId);
463	
464	    HCCL_INFO("[RankInfoDetectService::%s] end.", __func__);
465	}
466	
467	RankInfoDetectService::~RankInfoDetectService() { DECTOR_TRY_CATCH("RankInfoDetectService", TearDown()); }
468	
469	} // namespace Hccl
