34	    constexpr u32 HOST_CONTROL_PORT_COUNT = 15;
35	    constexpr u32 HOST_BACKUP_ADDR_NET_LAYER = 3;
36	    constexpr const char* BACKUP_ADDR_FIELD = "backup_addr";
37	    constexpr const char* ADDR_FIELD = "addr";
38	    constexpr const char* ADDR_TYPE_FIELD = "addr_type";
39	
40	    void FillCommAddr(CommAddr& commAddr, const IpAddress& ipAddr)
41	    {
42	        const s32 family = ipAddr.GetFamily();
43	        if (family == AF_INET) {
44	            commAddr.type = COMM_ADDR_TYPE_IP_V4;
45	            commAddr.addr = ipAddr.GetBinaryAddress().addr;
46	        } else if (family == AF_INET6) {
47	            commAddr.type = COMM_ADDR_TYPE_IP_V6;
48	            commAddr.addr6 = ipAddr.GetBinaryAddress().addr6;
49	        } else {
50	            THROW<InvalidParamsException>(
51	                StringFormat("[%s] invalid commAddrType, hostAddr[%s].", __func__, ipAddr.Describe().c_str()));
52	        }
53	    }
54	
55	    void BuildHostAddrCandidates(const nlohmann::json& addrJson, std::vector<IpAddress>& candidates)
56	    {
57	        // 候选顺序固定为主地址在前、备地址按配置顺序在后，选择时取首个探测成功的地址。
58	        std::string addrType;
59	        std::string primaryAddr;
60	        const std::string msgAddrType = "get host addr_type failed";
61	        TRY_CATCH_THROW(InvalidParamsException, msgAddrType, addrType = GetJsonProperty(addrJson, ADDR_TYPE_FIELD););
62	        const std::string msgPrimaryAddr = "get primary host addr failed";
63	        TRY_CATCH_THROW(InvalidParamsException, msgPrimaryAddr, primaryAddr = GetJsonProperty(addrJson, ADDR_FIELD););
64	        IpAddress primaryIpAddress;
65	        const std::string msgParsePrimaryAddr = "parse primary host addr failed";
66	        TRY_CATCH_THROW(InvalidParamsException, msgParsePrimaryAddr,
67	                        AddressInfo::ParseAddrByType(addrType, primaryAddr, primaryIpAddress););
68	        candidates.clear();
69	        candidates.emplace_back(primaryIpAddress);
70	
71	        std::vector<IpAddress> backupAddrs;
72	        const std::string msgParseBackupAddr = "parse backup host addr failed";
73	        TRY_CATCH_THROW(InvalidParamsException, msgParseBackupAddr,
74	                        AddressInfo::ParseBackupAddrs(addrJson.at(BACKUP_ADDR_FIELD), addrType, backupAddrs););
75	        candidates.insert(candidates.end(), backupAddrs.begin(), backupAddrs.end());
76	    }
77	
78	    void CollectLayer3AddrJsons(nlohmann::json& localDevInfoJson, std::vector<nlohmann::json*>& addrJsons)
79	    {
80	        // 仅返回 netLayer3 及以上且配置了 backup_addr 的可写地址节点，其他地址直接沿用主 addr。
81	        addrJsons.clear();
82	        CHK_PRT_THROW(
83	            !localDevInfoJson.contains("level_list") || !localDevInfoJson.at("level_list").is_array(),
84	            HCCL_ERROR("[%s] level_list is missing or is not an array.", __func__), InvalidParamsException,
85	            "level_list is missing or is not an array");
86	        for (auto& levelJson : localDevInfoJson.at("level_list")) {
87	            if (!levelJson.contains("rank_addr_list") || !levelJson["rank_addr_list"].is_array()) {
88	                continue;
89	            }
90	            u32 netLayer = 0;
91	            const std::string msgNetLayer = "get net_layer failed";
92	            TRY_CATCH_THROW(InvalidParamsException, msgNetLayer,
93	                            netLayer = GetJsonPropertyUInt(levelJson, "net_layer"););
94	            if (netLayer < HOST_BACKUP_ADDR_NET_LAYER) {
95	                continue;
96	            }
97	            for (auto& addrJson : levelJson["rank_addr_list"]) {
98	                if (!addrJson.contains(BACKUP_ADDR_FIELD)) {
99	                    HCCL_WARNING("[%s] backup_addr is not configured, use primary addr without probing.", __func__);
100	                    continue;
101	                }
102	                addrJsons.push_back(&addrJson);
103	            }
104	        }
105	    }
106	
107	    std::string QueryTopoFilePathByDevice()
108	    {
109	        const size_t bufSize = 1024;
110	        auto devLogicId = HrtGetDevice();
111	        auto devPhyId = HrtGetDevicePhyIdByIndex(devLogicId);
112	        std::vector<char> buffer(bufSize, '\0');
113	        int result = TopoAddrInfoGetTopoFilePath(devPhyId, buffer.data(), buffer.size());
114	        CHK_PRT_THROW(
115	            result != 0, HCCL_ERROR("[%s] Get topo file path failed.", __func__), InvalidParamsException,
116	            "Get topo file path failed.");
117	        return std::string(buffer.data());
118	    }
119	
120	    void CheckTopoFilePath(const std::string& topoFilePath)
121	    {
122	        char resolvedPath[PATH_MAX] = {0};
123	        CHK_PRT_THROW(
124	            realpath(topoFilePath.c_str(), resolvedPath) == nullptr,
125	            HCCL_ERROR("[%s] topo_file_path[%s] is not a valid real path", __func__, topoFilePath.c_str()),
126	            InvalidParamsException, "topo_file_path error");
127	    }
128	
129	    std::string GetRootInfoTopoFilePath()
130	    {
131	        std::string filePath = "/etc/hccl_rootinfo.json";
132	        JsonParser jsonParser{};
133	        nlohmann::json parseJson{};
134	        std::string topoFilePath{};
135	        std::ifstream file(filePath);
136	        if (file.good()) {
137	            jsonParser.ParseFileToJson(filePath, parseJson);
138	            std::string msgRankTopoFile = "error occurs when parser object of propName \"topo_file_path\"";
139	            TRY_CATCH_THROW(InvalidParamsException, msgRankTopoFile,
140	                            topoFilePath = GetJsonProperty(parseJson, "topo_file_path"););
141	        } else {
142	            topoFilePath = QueryTopoFilePathByDevice();
143	        }
144	
145	        CheckTopoFilePath(topoFilePath);
146	        return topoFilePath;
147	    }
