149	
150	void RankInfoDetectClient::Setup(RankTableInfo& rankTable)
151	{
152	    // 1. 构造localRankTable
153	    RankTableInfo localRankTable{};
154	    ConstructRankTable(localRankTable);
155	
156	    // 若启用单卡多进程抢占端口则执行
157	    SocketManager::ServerInitAll(localRankTable.ranks[0]);
158	    HostListenPortDetect(localRankTable.ranks[0]);
159	
160	    // 2. 连接root节点
161	    Connect();
162	
163	    // 3. 发送本端agentId和rankSize
164	    SendAgentIdAndRankSize();
165	
166	    // 4. 发送给root节点
167	    SendLocalRankTable(localRankTable);
168	
169	    // 5. 接收完整rankTable
170	    RecvRankTable();
171	    rankTable = rankTable_;
172	}
173	
174	void RankInfoDetectClient::Connect()
175	{
176	    clientSocket_->Connect();
177	    CheckStatus();
