180	void RankInfoDetectClient::CheckStatus()
181	{
182	    HCCL_DEBUG("[RankInfoDetectClient::%s] start.", __func__);
183	
184	    auto startTime = std::chrono::steady_clock::now();
185	    auto timeout = std::chrono::seconds(EnvConfig::GetInstance().GetSocketConfig().GetLinkTimeOut());
186	
187	    while (true) {
188	        bool isTimeout = ((std::chrono::steady_clock::now() - startTime) >= timeout);
189	        if (isTimeout) {
190	            HCCL_ERROR(
191	                "[RankInfoDetectClient::%s] get connected status socket timeout! timeout[%lld s]", __func__, timeout);
192	            RPT_INPUT_ERR(
193	                isTimeout, "EI0015", std::vector<std::string>({"error_reason"}),
194	                std::vector<std::string>({StringFormat(
195	                    "Receiving message from the root node timed out "
196	                    "Timeout was set to %lld seconds. Check whether node rankId[%u] reports an error.",
197	                    static_cast<long long>(timeout.count()), rankId_)}));
198	            // 建链超时后，sleep 20s，避免上层应用提前退出，确保其他正常 client 能够收到 server 发出的临终遗言
199	            sleep(WAIT_ERROR_BROADCAST_TIME);
200	            THROW<TimeoutException>("client get connection timeout");
201	        }
202	
203	        if (clientSocket_->GetStatus() == SocketStatus::OK) {
204	            HCCL_DEBUG("[RankInfoDetectClient::%s] client get socket connection success.", __func__);
205	            break;
206	        }
207	    }
208	
209	    HCCL_INFO("[RankInfoDetectClient::%s] end, connect ok.", __func__);
210	}
