265	void CheckRootInfoJson(const nlohmann::json& parseJson)
266	{
267	    // check version
268	    std::string version{};
269	    std::string msgVersion = "error occurs when parser rootinfo object of propName \"version\"";
270	    TRY_CATCH_THROW(InvalidParamsException, msgVersion, version = GetJsonProperty(parseJson, "version"););
271	    if (version != "2.0") {
272	        RPT_INPUT_ERR(
273	            true, "EI0016", std::vector<std::string>({"value", "variable", "expect"}),
274	            std::vector<std::string>({version, "version", "2.0"}));
275	        HCCL_ERROR("[%s] failed with version [%s] is not \"2.0\".", __func__, version.c_str());
276	        THROW<InvalidParamsException>("version error");
277	    }
278	
279	    // parser topo_file_path
280	    std::string topoFilePath{};
281	    std::string msgRankTopoFile = "error occurs when parser object of propName \"topo_file_path\"";
282	    TRY_CATCH_THROW(InvalidParamsException, msgRankTopoFile,
283	                    topoFilePath = GetJsonProperty(parseJson, "topo_file_path"););
284	
285	    // check topo_file_path
286	    char resolvedPath[PATH_MAX] = {0};
287	    bool isInvalidPath = (realpath(topoFilePath.c_str(), resolvedPath) == nullptr);
288	    if (isInvalidPath) {
289	        RPT_INPUT_ERR(
290	            true, "EI0016", std::vector<std::string>({"value", "variable", "expect"}),
291	            std::vector<std::string>({topoFilePath, "topo_file_path", "valid path"}));
292	        HCCL_ERROR("[%s] topo_file_path[%s] is not a valid real path", __func__, topoFilePath.c_str());
293	        THROW<InvalidParamsException>("topo_file_path error");
294	    }
295	
296	    // parser rank_count
297	    u32 rankCount{};
298	    std::string msgRankcount = "error occurs when parser object of propName \"rank_count\"";
299	    TRY_CATCH_THROW(InvalidParamsException, msgRankcount, rankCount = GetJsonPropertyUInt(parseJson, "rank_count"););
300	
301	    // parser rank_list
302	    nlohmann::json rankJsons{};
303	    std::string msgRanklist = "error occurs when parser object of propName \"rank_list\"";
304	    TRY_CATCH_THROW(InvalidParamsException, msgRanklist, GetJsonPropertyList(parseJson, "rank_list", rankJsons););
305	
306	    // check rank_count
307	    bool isRankCountMismatch = (rankCount != rankJsons.size());
308	    if (isRankCountMismatch) {
309	        RPT_INPUT_ERR(
310	            true, "EI0016", std::vector<std::string>({"value", "variable", "expect"}),
311	            std::vector<std::string>({std::to_string(rankCount), "rankCount", std::to_string(rankJsons.size())}));
312	        HCCL_ERROR(
313	            "[%s] failed with rankCount is not equal to rank_list size."
314	            "rankCount[%u], ranks.size[%u]",
315	            __func__, rankCount, rankJsons.size());
316	        THROW<InvalidParamsException>("rankCount error");
317	    }
318	}
