320	void RankInfoDetectClient::ConstructRankTable(RankTableInfo& localRankTable)
321	{
322	    HCCL_INFO("[RankInfoDetectClient::%s] start.", __func__);
323	
324	    // 单P场景处理
325	    CHK_PRT_RET((rankSize_ == 1), ConstructSingleRank(localRankTable), );
326	
327	    // 1. 解析文件topoInfo.json
328	    std::string filePath = "/etc/hccl_rootinfo.json";
329	    JsonParser jsonParser{};
330	    nlohmann::json parseJson{};
331	    std::ifstream file(filePath);
332	    if (file.good()) {
333	        jsonParser.ParseFileToJson(filePath, parseJson);
334	    } else {
335	        size_t bufSize;
336	        s32 result = TopoAddrInfoGetSize(devPhyId_, &bufSize); // 获取rankInfo大小，用于提前分配内存
337	        CHK_PRT_THROW(
338	            result != 0 || bufSize > MAX_BUFFER_LEN,
339	            HCCL_ERROR("[RankInfoDetectClient::%s] Get rankinfo size failed.", __func__), InvalidParamsException,
340	            "Get rankinfo size failed.");
341	        std::vector<char> buffer(bufSize, '\0');
342	        result = TopoAddrInfoGet(devPhyId_, buffer.data(), &bufSize); // 获取rankInfo 并更新大小
343	        CHK_PRT_THROW(
344	            result != 0, HCCL_ERROR("[RankInfoDetectClient::%s] Get rankinfo failed.", __func__),
345	            InvalidParamsException, "Get rankinfo size failed.");
346	        std::string jsonString(buffer.data(), bufSize);
347	        // 将生成的info信息转换成json文件
348	        parseJson = nlohmann::json::parse(jsonString);
349	    }
350	    CheckRootInfoJson(parseJson);
351	
352	    // 2. 获取当前devPhyId_对应的devInfo
353	    nlohmann::json localDevInfoJson{};
354	    GetLocalDevInfoJson(parseJson, localDevInfoJson);
355	    // 3. 在反序列化和上报本地 RankTable 前改写 addr，确保后续全局 RankTable 和 RankGraph 使用选中地址
356	    SelectLocalHostBackupAddr(localDevInfoJson);
357	
358	    // 4. 组rankTable的json格式
359	    nlohmann::json localRankTableJson{};
360	    GetLocalRankTableJson(parseJson, localRankTableJson);
361	    localRankTableJson["rank_list"].push_back(localDevInfoJson); // 添加localDevInfoJson
362	
363	    // 5. 反序列化获得RankTableInfo
364	    std::string msgDeserialize = "error occurs when localRankTable Deserialize";
365	    TRY_CATCH_THROW(InvalidParamsException, msgDeserialize, localRankTable.Deserialize(localRankTableJson, false););
366	
367	    CHK_PRT_THROW(
368	        localRankTable.ranks.empty(), HCCL_ERROR("[RankInfoDetectClient::%s] local rank table has no rank.", __func__),
369	        InvalidParamsException, "local rank table has no rank");
370	    CHK_PRT_CONT(
371	        GetLocalTlsStatus(localRankTable.ranks[0].tlsStatus),
372	        HCCL_WARNING("[GetLocalTlsStatus] Can not get TlsStatus"));
373	    HCCL_INFO("[RankInfoDetectClient::%s] end.", __func__);
374	}
