376	void RankInfoDetectClient::ProbeHostRoceAddr(const IpAddress& hostAddr, bool& isAvailable) const
377	{
378	    isAvailable = false;
379	    // hostAddr 来自 netLayer3 的 rank_addr_list，是 RoCE 数据通信地址；它不同于 RootInfoDetect
380	    // 使用的 rootHandle.ip，后者只负责控制面 socket 建链。
381	    EndpointDesc endpointDesc{};
382	    const HcommResult initRet = EndpointDescInit(&endpointDesc, 1);
383	    CHK_PRT_THROW(
384	        initRet != HCCL_SUCCESS, HCCL_ERROR("[%s] EndpointDescInit failed, ret[%d].", __func__, initRet),
385	        InternalException, StringFormat("[%s] EndpointDescInit failed, ret[%d]", __func__, initRet));
386	    endpointDesc.protocol = COMM_PROTOCOL_ROCE;
387	    endpointDesc.loc.locType = ENDPOINT_LOC_TYPE_HOST;
388	    const std::string msgFillCommAddr = "fill host RoCE endpoint address failed";
389	    TRY_CATCH_THROW(InvalidParamsException, msgFillCommAddr, FillCommAddr(endpointDesc.commAddr, hostAddr););
390	
391	    EndpointHandle endpointHandle = nullptr;
392	    const HcommResult createRet = HcommEndpointCreate(&endpointDesc, &endpointHandle);
393	    // 仅网络错误允许上层继续尝试备用地址，其他错误按不可恢复异常立即终止。
394	    if (createRet == HCCL_E_NETWORK) {
395	        HCCL_WARNING(
396	            "[%s] host addr is unavailable, hostAddr[%s], ret[%d].", __func__, hostAddr.Describe().c_str(), createRet);
397	        return;
398	    } else if (createRet != HCCL_SUCCESS) {
399	        HCCL_ERROR(
400	            "[%s] HcommEndpointCreate failed, hostAddr[%s], ret[%d].", __func__, hostAddr.Describe().c_str(),
401	            createRet);
402	        THROW<InternalException>(StringFormat("[%s] HcommEndpointCreate failed, ret[%d]", __func__, createRet));
403	    }
404	    if (endpointHandle != nullptr) {
405	        // Endpoint 仅用于可用性探测，不参与后续通信，探测成功后立即释放。
406	        const HcommResult destroyRet = HcommEndpointDestroy(endpointHandle);
407	        CHK_PRT_THROW(
408	            destroyRet != HCCL_SUCCESS,
409	            HCCL_ERROR(
410	                "[%s] HcommEndpointDestroy failed, hostAddr[%s], ret[%d].", __func__, hostAddr.Describe().c_str(),
411	                destroyRet),
412	            InternalException, StringFormat("[%s] HcommEndpointDestroy failed, ret[%d]", __func__, destroyRet));
413	    }
414	    isAvailable = true;
415	    HCCL_INFO(
416	        "[%s] host addr probe success, devPhyId[%u], rankId[%u], hostAddr[%s].", __func__, devPhyId_, rankId_,
417	        hostAddr.Describe().c_str());
418	}
