420	void RankInfoDetectClient::SelectLocalHostBackupAddr(nlohmann::json& localDevInfoJson)
421	{
422	    const bool isLevelListInvalid = localDevInfoJson.empty() || !localDevInfoJson.contains("level_list")
423	                                    || !localDevInfoJson["level_list"].is_array();
424	    CHK_PRT_THROW(
425	        isLevelListInvalid,
426	        HCCL_ERROR(
427	            "[%s] level_list is missing or is not an array, devPhyId[%u], rankId[%u].", __func__, devPhyId_, rankId_),
428	        InvalidParamsException, "level_list is missing or is not an array");
429	    std::vector<nlohmann::json*> addrJsons;
430	    const std::string msgCollectLayer3Addr = "collect netLayer3 addr failed";
431	    TRY_CATCH_THROW(InvalidParamsException, msgCollectLayer3Addr, CollectLayer3AddrJsons(localDevInfoJson, addrJsons););
432	    if (addrJsons.empty()) {
433	        HCCL_DEBUG("[%s] no netLayer3+ addr with backup_addr needs probing.", __func__);
434	        return;
435	    }
436	    // 主备选择只依赖 RootInfo 的 net_layer 字段，不读取或构建 PhyTopo。
437	    // 对每个 netLayer3+ 地址独立探测主 addr；主地址不可用时，再按配置顺序逐个尝试 backup_addr。
438	    for (auto* addrJson : addrJsons) {
439	        SelectAvailableHostAddr(*addrJson);
440	    }
441	    HCCL_INFO(
442	        "[%s] end, devPhyId[%u], rankId[%u], addrConfigNum[%zu].", __func__, devPhyId_, rankId_, addrJsons.size());
443	}
444	
445	void RankInfoDetectClient::SelectAvailableHostAddr(nlohmann::json& addrJson)
446	{
447	    std::vector<IpAddress> candidates;
448	    const std::string msgBuildCandidates = "build host addr candidates failed";
449	    TRY_CATCH_THROW(InvalidParamsException, msgBuildCandidates, BuildHostAddrCandidates(addrJson, candidates););
450	    HCCL_INFO(
451	        "[%s] devPhyId[%u], rankId[%u], primaryAddr[%s], backupAddrSize[%zu], "
452	        "candidateSize[%zu].",
453	        __func__, devPhyId_, rankId_, candidates.front().Describe().c_str(), candidates.size() - 1, candidates.size());
454	
455	    // HCCL_E_NETWORK 是可恢复错误，通过 isAvailable 继续尝试下一个候选地址；
456	    // 其他异常不在此处恢复。
457	    for (std::size_t idx = 0; idx < candidates.size(); ++idx) {
458	        bool isAvailable = false;
459	        ProbeHostRoceAddr(candidates[idx], isAvailable);
460	        if (isAvailable) {
461	            UpdateSelectedHostAddr(addrJson, candidates, idx);
462	            return;
463	        }
464	        if (idx == candidates.size() - 1) {
465	            THROW<NetworkApiException>(StringFormat("[%s] all host addr candidates are unavailable", __func__));
466	        }
467	        HCCL_WARNING(
468	            "[%s] host addr is unavailable, try next candidate, "
469	            "devPhyId[%u], rankId[%u], candidateAddr[%s], candidateIndex[%zu].",
470	            __func__, devPhyId_, rankId_, candidates[idx].Describe().c_str(), idx);
471	    }
472	}
