557	// 解析接收到的rank table信息
558	void RankInfoDetectClient::ParseRankTable(vector<char>& rankInfoMsg)
559	{
560	    HCCL_INFO("[RankInfoDetectClient::%s] start.", __func__);
561	
562	    // 消息格式: [ranktable大小(u32, 4字节)][ranktable数据(n字节)][step(4字节)][failedAgentIdList]
563	    BinaryStream binStream(rankInfoMsg);
564	
565	    // 解析localRankInfo
566	    rankTable_ = RankTableInfo(binStream);
567	    rankTable_.Dump();
568	
569	    // 解析step
570	    u32 receivedStep;
571	    binStream >> receivedStep;
572	
573	    // 解析failedAgentIdList
574	    std::string failedAgentIdList;
575	    binStream >> failedAgentIdList;
576	    if (failedAgentIdList.size() > 0) {
577	        // 建链失败时，打印 root 节点发来的临终遗言
578	        HCCL_ERROR(
579	            "[RankInfoDetectClient::%s] TopoDetect ERROR occur, failedRankIdList[%s]", __func__,
580	            failedAgentIdList.c_str());
581	    }
582	
583	    HCCL_INFO("[RankInfoDetectClient::%s] end.", __func__);
584	}
