602	
603	    // 校验rankCount符合预期
604	    if (rankTable_.rankCount != rankSize_) {
605	        THROW<InvalidParamsException>(StringFormat(
606	            "[RankInfoDetectClient::%s] rank_count[%u] does not match"
607	            " rankSize_[%u].",
