615	    CHK_PRT_THROW(
616	        ret != HCCL_SUCCESS,
617	        HCCL_ERROR("[RankInfoDetectClient::%s] tls consistency verify failed, ret[%d]", __func__, ret),
618	        InvalidParamsException, "tls consistency verify failed");
