642	void RankInfoDetectClient::ReportTlsConfigurationError(
643	    const std::string& tlsInconsistentTlsType, const std::string& tlsEnableRankStr,
644	    const std::string& tlsDisableRankStr, const std::string& tlsUnknownRankStr) const
645	{
646	    std::string expectMessage = "\"All ranks are consistent. Current status: rankList for enabled tls: "
647	                                + tlsEnableRankStr + "; rankList for disabled tls: " + tlsDisableRankStr
648	                                + "; rankList for query failure tls: " + tlsUnknownRankStr + ".\"";
649	    std::string errormessage
650	        = "Value \"" + tlsInconsistentTlsType + "\" for config \"tls\" is invalid. Expected: " + expectMessage;
651	
652	    RPT_INPUT_ERR(
653	        true, "EI0016", std::vector<std::string>({"value", "variable", "expect"}),
654	        std::vector<std::string>({tlsInconsistentTlsType, "\"tls\"", expectMessage}));
655	
656	    HCCL_ERROR("[ReportTlsConfigurationError][RanktableCheck] %s", errormessage.c_str());
657	}
658	
659	HcclResult RankInfoDetectClient::VerifyTlsConsistency() const
660	{
661	    bool isSupportCheckTlsStatus = true; // 用于标识是否存在不支持查询Tls开关状态的情况
662	    bool isTlsConsistent = true;         // 用于标识TLS开关状态是否一致
663	    std::vector<u32> tlsEnableRank;
664	    std::vector<u32> tlsDisableRank;
665	    std::vector<u32> tlsUnknownRank;
666	
667	    for (const auto& rankInfo : rankTable_.ranks) {
668	        if (rankInfo.tlsStatus == TlsStatus::ENABLE) {
669	            tlsEnableRank.push_back(rankInfo.rankId);
670	        } else if (rankInfo.tlsStatus == TlsStatus::DISABLE) {
671	            tlsDisableRank.push_back(rankInfo.rankId);
672	        } else {
673	            isSupportCheckTlsStatus = false;
674	            tlsUnknownRank.push_back(rankInfo.rankId);
675	        }
676	    }
677	
678	    // 将卡的信息汇总成string
679	    std::string tlsEnableRankStr;
680	    std::string tlsDisableRankStr;
681	    std::string tlsUnknownRankStr;
682	    GenerateTlsStatusStr(tlsEnableRankStr, tlsEnableRank);
683	    GenerateTlsStatusStr(tlsDisableRankStr, tlsDisableRank);
684	    if (!isSupportCheckTlsStatus) {
685	        GenerateTlsStatusStr(tlsUnknownRankStr, tlsUnknownRank);
686	    }
687	
688	    std::string tlsInconsistentTlsType;
689	    if (!tlsEnableRank.empty() && !tlsDisableRank.empty()) {
690	        isTlsConsistent = false;
691	        tlsInconsistentTlsType = (tlsDisableRank.size() <= tlsEnableRank.size()) ? "Disable" : "Enable";
692	    }
693	
694	    // 四种不同情况
695	    if (isTlsConsistent && isSupportCheckTlsStatus) {
696	        // 1.通信域所有卡都支持查询TLS开关状态，并且TLS开关状态都是一致的。
697	        HCCL_INFO("[Verify][TlsConsistency] All ranks tlsStatus are consistent");
698	    } else if (!isTlsConsistent && isSupportCheckTlsStatus) {
699	        // 2.通信域所有卡都支持查询TLS开关状态，但是TLS开关状态存在不一致，报错。
700	        ReportTlsConfigurationError(tlsInconsistentTlsType, tlsEnableRankStr, tlsDisableRankStr, tlsUnknownRankStr);
701	        return HCCL_E_PARA;
702	    } else if (isTlsConsistent && !isSupportCheckTlsStatus) {
703	        // 3.通信域内的部分卡不支持查询TLS开关状态，目前能查询到的卡的TLS开关状态是一致的，打印warning提醒
704	        HCCL_WARNING(
705	            "[Verify][TlsConsistency] Some ranks do not support to check tlsStatus, "
706	            "not support rankId: [%s]",
707	            tlsUnknownRankStr.c_str());
708	    } else {
709	        // 4.通信域内的部分卡不支持查询TLS开关状态，但是目前能查询到的卡的TLS开关状态已经不一致，报错
710	        ReportTlsConfigurationError(tlsInconsistentTlsType, tlsEnableRankStr, tlsDisableRankStr, tlsUnknownRankStr);
711	        return HCCL_E_PARA;
712	    }
713	
714	    return HCCL_SUCCESS;
715	}
716	
717	void RankInfoDetectClient::HostListenPortDetect(NewRankInfo& rankInfo)
718	{
719	    std::string topoPath = GetRootInfoTopoFilePath();
720	    PhyTopoBuilder::GetInstance().Build(topoPath);
721	    auto devLogicId = HrtGetDevice();
722	    u32 devPhyId = rankInfo.deviceId;
723	    for (auto& rankLevelInfo : rankInfo.rankLevelInfos) {
724	        shared_ptr<Graph<PhyTopo::Node, PhyTopo::Link>> graph
725	            = PhyTopo::GetInstance()->GetTopoGraph(rankLevelInfo.netLayer);
726	        if (graph == nullptr) {
727	            HCCL_DEBUG("[RankInfoDetectClient::%s]Can't find the layout %u Graph!", __func__, rankLevelInfo.netLayer);
728	            continue;
729	        }
730	        std::vector<std::shared_ptr<PhyTopo::Link>> links = graph->GetEdges(rankInfo.localId);
731	        for (auto& link : links) {
732	            if (link->GetSourceIFace()->GetPos() != AddrPosition::HOST) {
733	                continue;
734	            }
735	            const std::set<LinkProtocol>& protocols = link->GetLinkProtocols();
736	            for (auto& protocol : protocols) {
737	                LinkProtoType protoType = LinkProtocol2LinkProtoType(protocol);
738	                if (protoType != LinkProtoType::RDMA || rankLevelInfo.rankAddrs.empty()) {
739	                    continue;
740	                }
741	                HCCL_DEBUG("[SocketManager::%s] find the host rdma link %s", __func__, link->Describe().c_str());
742	                const IpAddress& hostIp = rankLevelInfo.rankAddrs[0].addr;
743	                uint32_t hostPort = 0;
744	                SetupHostListenPort(devLogicId, devPhyId, hostIp, hostPort);
745	                rankInfo.hostPort = hostPort;
746	                return;
747	            }
748	        }
749	    }
750	}
751	
752	void RankInfoDetectClient::SetupHostListenPort(
753	    u32 devLogicId, u32 devPhyId, const IpAddress& hostIp, uint32_t& hostPort)
754	{
755	    std::lock_guard<std::mutex> lock(hostSocketLock_);
756	    u32 listenPort = HCCL_INVALID_PORT;
757	    auto portRange = EnvConfig::GetInstance().GetHostNicConfig().GetHostSocketPortRange();
758	    u32 basePort = EnvConfig::GetInstance().GetHostNicConfig().GetIfBasePort();
759	    if (portRange.empty() && basePort != HCCL_INVALID_PORT) {
760	        listenPort = basePort + devPhyId;
761	        HCCL_INFO("[RankInfoDetectClient::%s] BasePort is configured, listenPort[%u].", __func__, listenPort);
762	        hostPort = listenPort;
763	        return;
764	    }
765	
766	    if (portRange.empty()) {
767	        constexpr u32 HOST_CONTROL_BASE_PORT = 60000; // 控制面起始port
768	        HCCL_INFO(
769	            "[RankInfoDetectClient::%s] No port configuration, using default port range[%u, %u]", __func__,
770	            HOST_CONTROL_BASE_PORT, HOST_CONTROL_BASE_PORT + HOST_CONTROL_PORT_COUNT);
771	        SocketPortRange defaultRange = {HOST_CONTROL_BASE_PORT, HOST_CONTROL_BASE_PORT + HOST_CONTROL_PORT_COUNT};
772	        portRange.push_back(defaultRange);
773	    }
774	
775	    SocketHandle hostSocketHandle = HostSocketHandleManager::GetInstance().Create(devPhyId, hostIp);
776	    hostSocket_ = std::make_shared<Socket>(
777	        hostSocketHandle, hostIp, HCCL_INVALID_PORT, hostIp, "hostport_preempt", SocketRole::SERVER,
778	        NicType::HOST_NIC_TYPE);
779	    PreemptPortManager::GetInstance(devLogicId).ListenPreempt(hostSocket_, portRange, listenPort);
780	    HCCL_INFO("[RankInfoDetectClient::%s] preempt hostPort[%u] success.", __func__, listenPort);
781	    hostPort = listenPort;
782	}
783	
784	void RankInfoDetectClient::SocketTearDown(u32 devPhyId)
785	{
786	    std::lock_guard<std::mutex> lock(hostSocketLock_);
787	    if (hostSocket_ == nullptr) {
788	        return;
789	    }
790	    const IpAddress& hostIp = hostSocket_->GetLocalIp();
791	    auto devLogicId = HrtGetDevice();
792	    if (EnvConfig::GetInstance().GetHostNicConfig().GetHostSocketPortRange().size() > 0
793	        || EnvConfig::GetInstance().GetHostNicConfig().GetIfBasePort() == HCCL_INVALID_PORT) {
794	        // 若开启抢占监听端口
795	        PreemptPortManager::GetInstance(devLogicId).Release(hostSocket_);
796	    }
797	    hostSocket_ = nullptr;
798	    HostSocketHandleManager::GetInstance().Destroy(devPhyId, hostIp);
799	}
800	
801	void RankInfoDetectClient::TearDown()
802	{
803	    HCCL_INFO("[RankInfoDetectClient::%s] start.", __func__);
804	    SocketTearDown(devPhyId_);
805	
806	    // close socket
807	    clientSocket_->Close();
808	
809	    // deinit handle
810	    HostSocketHandleManager::GetInstance().Destroy(devPhyId_, clientSocket_->GetLocalIp());
811	
812	    // deinit ra in detach thread to avoid block main thread
813	    s32 deviceLogicId = HrtGetDevice();
814	    std::thread{[deviceLogicId]() {
815	        EXCEPTION_CATCH(
816	            HccpPeerManager::GetInstance().DeInit(deviceLogicId),
817	            HCCL_ERROR("[RankInfoDetectClient::TearDown] DeInit exception"));
818	    }}.detach();
819	
820	    HCCL_INFO("[RankInfoDetectClient::%s] end.", __func__);
821	}
822	
823	RankInfoDetectClient::~RankInfoDetectClient() { DECTOR_TRY_CATCH("RankInfoDetectClient", TearDown()); }
824	
825	} // namespace Hccl
