            "[%s] errNo[0x%016llx] RootInfoDetect failed, rootHandle[%s].", __func__, HCCL_ERROR_CODE(ret),
            identifier.c_str());
        rankTable.Dump();
        return ret;
    }

    // 打印ranktable
    rankTable.Dump();
